-- Schema migrations and DDL as generated by EF Core / Flyway / hand written scripts
CREATE TABLE [dbo].[Customers] ([Id] INT IDENTITY(1,1) NOT NULL, [Name] NVARCHAR(200) NOT NULL, [Email] NVARCHAR(320) NULL, [CreatedAt] DATETIME2(7) NOT NULL CONSTRAINT [DF_Customers_CreatedAt] DEFAULT (SYSUTCDATETIME()), [IsActive] BIT NOT NULL DEFAULT 1, CONSTRAINT [PK_Customers] PRIMARY KEY CLUSTERED ([Id] ASC));
CREATE TABLE dbo.Orders (Id BIGINT IDENTITY(1, 1) PRIMARY KEY, CustomerId INT NOT NULL, Total DECIMAL(18, 2) NOT NULL DEFAULT 0, Status NVARCHAR(20) NOT NULL, CreatedAt DATETIME2 NOT NULL DEFAULT GETUTCDATE(), CONSTRAINT FK_Orders_Customers FOREIGN KEY (CustomerId) REFERENCES dbo.Customers (Id) ON DELETE CASCADE);
CREATE TABLE dbo.Products (Id INT IDENTITY PRIMARY KEY, Sku VARCHAR(50) NOT NULL UNIQUE, Name NVARCHAR(MAX) NULL, Price MONEY NOT NULL, RowVer ROWVERSION, Guid UNIQUEIDENTIFIER NOT NULL DEFAULT NEWID(), CHECK (Price >= 0));
CREATE TABLE #staging (Id INT, Payload NVARCHAR(MAX));
CREATE TABLE dbo.Computed (A INT, B INT, Total AS (A + B), Doubled AS A * 2 PERSISTED);
ALTER TABLE [dbo].[Customers] ADD [Phone] NVARCHAR(30) NULL;
ALTER TABLE dbo.Customers ADD Region VARCHAR(10) NULL, Tier TINYINT NOT NULL CONSTRAINT DF_Cust_Tier DEFAULT 0;
ALTER TABLE dbo.Customers ALTER COLUMN Name NVARCHAR(400) NOT NULL;
ALTER TABLE dbo.Customers DROP COLUMN Phone;
ALTER TABLE dbo.Customers DROP CONSTRAINT DF_Cust_Tier;
ALTER TABLE dbo.Orders ADD CONSTRAINT CK_Orders_Total CHECK (Total >= 0);
ALTER TABLE dbo.Orders WITH CHECK ADD CONSTRAINT FK_Orders_Cust FOREIGN KEY (CustomerId) REFERENCES dbo.Customers (Id);
ALTER TABLE dbo.Orders NOCHECK CONSTRAINT FK_Orders_Cust;
ALTER TABLE dbo.Orders ADD CONSTRAINT UQ_Orders_Ref UNIQUE NONCLUSTERED (CustomerId, CreatedAt);
CREATE INDEX IX_Orders_CustomerId ON dbo.Orders (CustomerId);
CREATE NONCLUSTERED INDEX [IX_Orders_Status] ON [dbo].[Orders] ([Status] ASC) INCLUDE ([Total], [CreatedAt]) WHERE [Status] <> N'Closed' WITH (FILLFACTOR = 90, ONLINE = ON);
CREATE UNIQUE CLUSTERED INDEX UX_Products_Sku ON dbo.Products (Sku);
CREATE INDEX IX_Cust_Email ON dbo.Customers (Email DESC, Name);
DROP INDEX IX_Orders_CustomerId ON dbo.Orders;
DROP TABLE dbo.OldStuff;
DROP TABLE IF EXISTS dbo.Temp1;
DROP TABLE IF EXISTS #staging;
CREATE VIEW dbo.vw_ActiveCustomers AS SELECT Id, Name, Email FROM dbo.Customers WHERE IsActive = 1;
CREATE OR ALTER VIEW dbo.vw_OrderTotals AS SELECT CustomerId, SUM(Total) AS Total FROM dbo.Orders GROUP BY CustomerId;
DROP VIEW IF EXISTS dbo.vw_Old;
CREATE SCHEMA Reporting;
CREATE SEQUENCE dbo.OrderNumbers AS BIGINT START WITH 1000 INCREMENT BY 1;
SELECT NEXT VALUE FOR dbo.OrderNumbers;
TRUNCATE TABLE dbo.Staging;
CREATE TYPE dbo.IdList AS TABLE (Id INT NOT NULL PRIMARY KEY);
SELECT * INTO #recent FROM dbo.Orders WHERE CreatedAt > DATEADD(DAY, -7, GETDATE());
SELECT Id, Name INTO dbo.CustomersBackup FROM dbo.Customers;
